private class DataStructure<E>{
  private class O{
     E elem;
     O next;
     public O(E e, O n)
     {
        this.elem = e;
        this.next = n;
     }
  }


  O h;
  int sz;
  public void add(E e)
  {
     h = new O(e, h);
     sz++;
  }
  public E next()
  {
     return h.elem;
  }
  public E remove()
  {
     E e = next();
     h = h.next;
     sz--;
     return e;
  }
  public boolean isEmpty() {
     return sz == 0;
  }
}

