int N = 3; 
int[][] ints = new int[N][N]; 
int[][] d; 
d = new int[][] {{1,0,-1,0},{0,1,0,-1}}; 
Queue<Integer> que = new LinkedList<>(); 
que.add(1); 
que.add(1); 
que.add(1); 
while(!que.isEmpty()) 
{ 
  int a = que.poll(); 
  int b = que.poll(); 
  int c = que.poll(); 
  if(Math.min(a, b) >= 0  
     && Math.max(a, b)  < N  
     && ints[a][b] == 0){ 
     ints[a][b] = c; 
     for(int i = 0;i<4;i++) 
     { 
        que.add(a+d[0][i]); 
        que.add(b+d[1][i]); 
        que.add(c+1); 
     } 
  } 
} 
out.println(Arrays.toString(ints[N-1])); 
